use std::{fs,path::PathBuf,process::Command,sync::atomic::{AtomicU64,Ordering}};
use sha2::{Digest,Sha256};
static NEXT:AtomicU64=AtomicU64::new(0);
struct Fixture(PathBuf);
impl Fixture{fn new()->Self{let path=std::env::temp_dir().join(format!("justfit-source-cli-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));fs::create_dir(&path).unwrap();Self(path)}fn project(&self)->PathBuf{let root=self.0.join("project");fs::create_dir_all(root.join("config/nodes")).unwrap();let source=PathBuf::from(env!("CARGO_MANIFEST_DIR")).parent().unwrap().parent().unwrap().to_path_buf();let bytes=fs::read(source.join("config/nodes/m4.json")).unwrap();fs::write(root.join("config/nodes/m4.json"),&bytes).unwrap();fs::write(root.join("package-manifest.json"),serde_json::to_vec(&serde_json::json!({"config/nodes/m4.json":format!("{:x}",Sha256::digest(bytes))})).unwrap()).unwrap();root}}
impl Drop for Fixture{fn drop(&mut self){fs::remove_dir_all(&self.0).unwrap();}}
fn cli()->Command{let binary=std::env::var_os("JUSTFIT_TEST_SOURCE_SERVE_CLI").unwrap_or_else(||env!("CARGO_BIN_EXE_justfit-rs").into());let mut c=Command::new(binary);c.env("PATH","");c}
#[test]fn source_flags_are_public_and_textonly_plan_disables_media_without_downloads(){let fixture=Fixture::new();let project=fixture.project();let output=cli().args(["serve","--project"]).arg(&project).args(["--node","m4","--model","/not-downloaded","--draft-model","/local-draft","--language-only","--offline","--dry-run"]).output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let v:serde_json::Value=serde_json::from_slice(&output.stdout).unwrap();assert!(v["config"]["vision"].is_null());assert!(!project.join("local-state").exists());let help=cli().args(["serve","--help"]).output().unwrap();let help=String::from_utf8(help.stdout).unwrap();for flag in ["--draft-model","--language-only","--offline"]{assert!(help.contains(flag));}}
#[test]fn textonly_rejects_conflicting_vision_options_before_workspace_creation(){let fixture=Fixture::new();for flag in ["--vision-profile","--ane-manifest"]{let project=fixture.0.join("not-created");let mut c=cli();c.args(["serve","--project"]).arg(&project).args(["--node","m4","--language-only",flag,"https://example.invalid/asset"]);if flag=="--ane-manifest"{c.args(["--ane-manifest-sha256",&"a".repeat(64)]);}let out=c.output().unwrap();assert_eq!(out.status.code(),Some(2));assert!(String::from_utf8_lossy(&out.stderr).contains("--language-only"));assert!(!project.exists());}}
